{"command": "cd /workspace && python3 - <<'PY'
import numpy as np, base64, json, subprocess, os

def b64(pcm, encoding='int16'):
    if encoding=='int16':
        data=pcm.astype('<i2').tobytes()
    else:
        data=pcm.astype('<f4').tobytes()
    return base64.b64encode(data).decode()

sr=44100
t=np.arange(sr*2)/sr
x=(np.sin(2*np.pi*220*t)*0.5*32767).astype('<i2')
print(len(x))
open('/tmp/sine.raw','wb').write(x.tobytes())
print(b64(x)[:50])
PY
