{"command": "cd /workspace && ft2 call sample_load '{"path":"/workspace/samples/kick.wav","instrument":1,"sample":0}' && ft2 call sample_set '{"instrument":1,"sample":0,"name":"kick","volume":64,"panning":128,"finetune":0,"relative_note":49,"loop_start":0,"loop_length":0,"flags":0}' && ft2 call module_render '{"path":"/tmp/fx4.wav","rate":44100,"bits":16,"amp":16,"loops":1,"start":0,"stop":1}' && python3 - <<'PY'
import wave, numpy as np
w=wave.open('/tmp/fx4.wav','rb'); x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2')
print('len',len(x),'max',x.max(),'min',x.min())
# find nonzero segments
nz=np.where(np.abs(x)>100)[0]
if len(nz): print('nz range', nz[0]/44100, nz[-1]/44100, 'count', len(nz))
for i in range(0,min(len(x),200000),4410):
    seg=x[i:i+4410]; print(round(i/44100,2), seg.max(), seg.min(), round(float(np.sqrt(np.mean(seg.astype(float)**2))),1))
PY"}

{"command": "cd /workspace && ft2 call sample_load '{"path":"/workspace/samples/kick.wav","instrument":1,"sample":0}' && ft2 call sample_set '{"instrument":1,"sample":0,"name":"kick","volume":64,"panning":128,"finetune":0,"relative_note":49,"loop_start":0,"loop_length":0,"flags":0}' && ft2 call module_render '{"path":"/tmp/fx4.wav","rate":44100,"bits":16,"amp":16,"loops":1,"start":0,"stop":1}' && python3 - <<'PY'
