import json
C,Cs,D,Ds,E,F,Fs,G,Gs,A,As,B = range(12)
def n(oct, idx): return oct*12+idx+1

def cell(pat,row,ch,note=0,instr=0,vol=0,eff=0,param=0):
    return {"name":"pattern_set_cell","arguments":{"pattern":pat,"row":row,"channel":ch,"note":note,"instrument":instr,"volume":vol,"effect":eff,"effect_param":param}}

KICK=1; SNARE=2; HATC=3; HATO=4; BASS=5; LEAD=6; ARP=7; PAD1=8; PAD2=9; PAD3=10; CRASH=11
calls=[]
patterns={}

def add(pat,row,ch,note=0,instr=0,vol=0,eff=0,param=0):
    patterns.setdefault(pat,[]).append((row,ch,note,instr,vol,eff,param))

def add_note(pat,row,ch,note,instr,vol):
    add(pat,row,ch,note,instr,vol,0,0)

def chord_notes(kind):
    return {
        'Am': (n(3,A), n(4,C), n(4,E)),
        'F':  (n(3,A), n(4,C), n(4,F)),
        'C':  (n(3,G), n(4,C), n(4,E)),
        'G':  (n(3,G), n(3,B), n(4,D)),
        'Em': (n(3,G), n(3,B), n(4,E)),
        'Dm': (n(3,F), n(3,A), n(4,D)),
        'E':  (n(3,E), n(3,Gs), n(3,B)),
    }[kind]

def arp_notes(kind):
    return {
        'Am': (n(3,A), n(4,C), n(4,E), n(4,A)),
        'F':  (n(3,F), n(3,A), n(4,C), n(4,F)),
        'C':  (n(3,C), n(3,E), n(3,G), n(4,C)),
        'G':  (n(3,G), n(3,B), n(4,D), n(4,G)),
        'Em': (n(3,E), n(3,G), n(3,B), n(4,E)),
        'Dm': (n(3,D), n(3,F), n(3,A), n(4,D)),
        'E':  (n(3,E), n(3,Gs), n(3,B), n(4,E)),
    }[kind]

def bass_notes(kind):
    return {
        'Am': (n(2,A), n(3,A)),
        'F':  (n(2,F), n(3,F)),
        'C':  (n(3,C), n(4,C)),
        'G':  (n(2,G), n(3,G)),
        'Em': (n(2,E), n(3,E)),
        'Dm': (n(2,D), n(3,D)),
        'E':  (n(2,E), n(3,E)),
    }[kind]

prog = {
    0: ['Am','F','C','G'],
    1: ['Am','F','C','G'],
    2: ['F','G','Em','Am'],
    3: ['Dm','E','Am','E'],
}
arp_idx=[0,2,3,2]*4

# pads + arp + bass for all patterns
for pat,chords in prog.items():
    for bar,ch in enumerate(chords):
        row=bar*16
        tri=chord_notes(ch)
        for i,chh in enumerate([PAD1,PAD2,PAD3]):
            add_note(pat,row,chh,tri[i],7+i,40)
    for bar,ch in enumerate(chords):
        notes=arp_notes(ch)
        for i in range(16):
            row=bar*16+i
            add_note(pat,row,ARP,notes[arp_idx[i]],ARP,38)
    for bar,ch in enumerate(chords):
        lo,hi=bass_notes(ch)
        for j in range(8):
            row=bar*16+j*2
            note=lo if j%2==0 else hi
            add_note(pat,row,BASS,note,BASS,50)

# drums full patterns 1,2,3
for pat in [1,2,3]:
    for row in [0,16,32,48]:
        add_note(pat,row,0,n(2,C),KICK,64)
    for row in [16,48]:
        add_note(pat,row,1,n(2,C),SNARE,52)
    for row in range(0,64,2):
        add_note(pat,row,2,n(2,C),HATC,30)
    for row in [14,30,46,62]:
        add_note(pat,row,3,n(2,C),HATO,40)
    if pat in [1,3]:
        add_note(pat,0,3,n(2,C),CRASH,56)

# intro drums
for row in [32,48]:
    add_note(0,row,0,n(2,C),KICK,60)
for row in [48,60,62]:
    add_note(0,row,1,n(2,C),SNARE,50)
for row in range(16,64,2):
    add_note(0,row,2,n(2,C),HATC,26)
