def cell(pat,row,ch,note=0,instr=0,vol=0,eff=0,param=0):
    return {"name":"pattern_set_cell","arguments":{"pattern":pat,"row":row,"channel":ch,"note":note,"instrument":instr,"volume":vol,"effect":eff,"effect_param":param}}

def build():
    calls=[]
    patterns={}
