            'E':  (n(3,E), n(3,Gs), n(3,B)),
        }[kind]

    def arp_notes(kind):
        return {
            'Am': (n(3,A), n(4,C), n(4,E), n(4,A)),
            'F':  (n(3,F), n(3,A), n(4,C), n(4,F)),
            'C':  (n(3,C), n(3,E), n(3,G), n(4,C)),
            'G':  (n(3,G), n(3,B), n(4,D), n(4,G)),
            'Em': (n(3,E), n(3,G), n(3,B), n(4,E)),
            'Dm': (n(3,D), n(3,F), n(3,A), n(4,D)),
            'E':  (n(3,E), n(3,Gs), n(3,B), n(4,E)),
        }[kind]

    def bass_notes(kind):
        return {
            'Am': (n(2,A), n(3,A)),
            'F':  (n(2,F), n(3,F)),
            'C':  (n(3,C), n(4,C)),
            'G':  (n(2,G), n(3,G)),
            'Em': (n(2,E), n(3,E)),
            'Dm': (n(2,D), n(3,D)),
            'E':  (n(2,E), n(3,E)),
        }[kind]

    prog = {0:['Am','F','C','G'], 1:['Am','F','C','G'], 2:['F','G','Em','Am'], 3:['Dm','E','Am','E']}
    arp_idx=[0,2,3,2]*4
    ARP_VOL=32
    PAD_VOL=38
    BASS_VOL=52

    for pat,chords in prog.items():
        # pad triads
        for bar,ch in enumerate(chords):
            row=bar*16
            tri=chord_notes(ch)
            for i,chh in enumerate([CH_PAD1,CH_PAD2,CH_PAD3]):
                add_note(pat,row,chh,tri[i],[PAD1,PAD2,PAD3][i],PAD_VOL)
        # arp 16ths
        for bar,ch in enumerate(chords):
            notes=arp_notes(ch)
            for i in range(16):
                row=bar*16+i
                add_note(pat,row,CH_ARP,notes[arp_idx[i]],ARP,ARP_VOL)
        # bass 8ths
        for bar,ch in enumerate(chords):
            lo,hi=bass_notes(ch)
            for j in range(8):
                row=bar*16+j*2
                add_note(pat,row,CH_BASS,lo if j%2==0 else hi,BASS,BASS_VOL)

